"""`lixto` CLI entrypoint (typer) with auto-discovering subcommands.

**Do not edit this file to add commands.** Drop a module in `src/lixto/cli/`
and it is mounted automatically at import time. The discovery contract, for
every non-private module found by `pkgutil.iter_modules(lixto.cli.__path__)`:

1. A module exposing `app: typer.Typer` (or, equivalently, `command:
   typer.Typer`) **and** `name: str` becomes a command group:
   `root.add_typer(module.app, name=module.name)` — e.g. `lixto db init`
   comes from `cli/db.py` with `name = "db"`.
2. A module exposing `register(root: typer.Typer) -> None` is called with the
   root app and registers whatever it wants — the way to add *top-level*
   commands such as `lixto status` or `lixto backfill`.
3. A module may do both (a group plus top-level commands).

Modules are mounted in alphabetical order; a module that exposes neither is
skipped silently (helpers are allowed to live here).
"""

from __future__ import annotations

import importlib
import logging
import pkgutil

import typer

# rich_markup_mode=None → plain click help (no rich boxes), so `lixto --help`
# stays greppable in scripts/CI (`lixto --help | grep '^ *db'`).
app = typer.Typer(help="lixto — AI procurement agent", rich_markup_mode=None)

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")


def discover(
    root: typer.Typer, package: str = __name__, path: list[str] | None = None
) -> list[str]:
    """Import every submodule of `package` and mount it on `root`.

    Returns the names of the modules that were mounted (group or `register`),
    in the order they were mounted — used by the tests and handy for debugging.
    """
    if path is None:
        path = list(importlib.import_module(package).__path__)

    mounted: list[str] = []
    for module_info in sorted(pkgutil.iter_modules(path), key=lambda m: m.name):
        if module_info.name.startswith("_"):
            continue
        module = importlib.import_module(f"{package}.{module_info.name}")

        sub = getattr(module, "app", None) or getattr(module, "command", None)
        name = getattr(module, "name", None)
        registered = False
        if isinstance(sub, typer.Typer) and isinstance(name, str):
            root.add_typer(sub, name=name)
            registered = True

        register = getattr(module, "register", None)
        if callable(register):
            register(root)
            registered = True

        if registered:
            mounted.append(module_info.name)

    return mounted


discover(app)


def main() -> None:
    app()
